from ver.caret import satisfies


def test_minor_bump():
    assert satisfies("1.5.0", "^1.2.3")


def test_too_low():
    assert not satisfies("1.2.2", "^1.2.3")


def test_next_major():
    assert not satisfies("2.0.0", "^1.2.3")


def test_minor_bump_allowed():
    assert satisfies("1.5.0", "^1.2.3")


def test_zero_major_locks_minor():
    assert satisfies("0.2.9", "^0.2.3")
    assert not satisfies("0.3.0", "^0.2.3")


def test_zero_minor_locks_patch():
    assert not satisfies("0.0.4", "^0.0.3")

